const input = $input.first();
const item = input.json.body || input.json;
const ticketId = 'IT-' + Date.now();
const binaryIn = input.binary || {};
const keys = Object.keys(binaryIn);
const hasAttachment = keys.length > 0;

let binaryOut = {};
let attachmentName = '';
if (hasAttachment) {
  const first = binaryIn[keys[0]];
  binaryOut = { attachment: first };
  attachmentName = first.fileName || 'attachment';
}

return [{
  json: {
    ticketId,
    employeeName: item.employeeName,
    employeeEmail: item.employeeEmail,
    department: item.department,
    category: item.category,
    priority: 'Unassigned',
    description: item.description,
    attachmentName,
    hasAttachment,
    status: 'Open'
  },
  binary: binaryOut
}];

// The Data Table node drops binary data and the hasAttachment/attachmentName
// flags. Re-attach them from the Prepare Ticket output so the notification
// email can include the uploaded screenshot.
const rows = $input.all();
const prepared = $('Prepare Ticket').all();
return rows.map((row, i) => {
  const p = prepared[i] || prepared[0];
  return {
    json: {
      ...row.json,
      hasAttachment: p.json.hasAttachment,
      attachmentName: p.json.attachmentName
    },
    binary: p.binary || {},
    pairedItem: { item: i }
  };
});
